import numpy as np

t = np.array([0.4, 1.3, 0.7, 2.2, 0.9])


def loglik(rate):
    return len(t) * np.log(rate) - rate * t.sum()


rate = 1.5
exact = len(t) / rate - t.sum()
for h in (1e-1, 1e-3, 1e-5, 1e-8, 1e-11):
    fwd = (loglik(rate + h) - loglik(rate)) / h
    cen = (loglik(rate + h) - loglik(rate - h)) / (2 * h)
    print(f"h={h:.0e}: forward error {abs(fwd - exact):.2e}, central error {abs(cen - exact):.2e}")

import numpy as np

x = np.array([1.0, 2.0, 3.0, 4.0])
y = 3.0 * x


def loss(th):
    return 0.5 * np.sum((y - th[0] * th[1] * x) ** 2)


def hessian(f, th, h=1e-4):
    H = np.zeros((2, 2))
    for i in range(2):
        for j in range(2):
            e_i, e_j = np.eye(2)[i] * h, np.eye(2)[j] * h
            H[i, j] = (
                f(th + e_i + e_j) - f(th + e_i - e_j) - f(th - e_i + e_j) + f(th - e_i - e_j)
            ) / (4 * h * h)
    return H


for th in (np.array([2.0, 1.5]), np.array([1.0, 3.0])):
    vals, vecs = np.linalg.eigh(hessian(loss, th))
    print(
        f"a={th[0]}, b={th[1]}: loss {loss(th):.1f}, eigenvalues {vals.round(4)}, flat direction {vecs[:, 0].round(3)}"
    )

import numpy as np

y = np.array([2.1, 3.4, 1.8, 2.9, 3.6, 2.2])
n = len(y)


def nll(th):
    mu, log_s = th
    return n * log_s + 0.5 * np.sum((y - mu) ** 2) / np.exp(2 * log_s)


def num_hess(th, h=1e-4):
    H = np.zeros((2, 2))
    for i in range(2):
        for j in range(2):
            ei, ej = np.eye(2)[i] * h, np.eye(2)[j] * h
            H[i, j] = (
                nll(th + ei + ej) - nll(th + ei - ej) - nll(th - ei + ej) + nll(th - ei - ej)
            ) / (4 * h * h)
    return H


mle = np.array([y.mean(), np.log(y.std())])
print("at the MLE, numerical Hessian:\n", num_hess(mle).round(4))
print(f"closed form diag(n/s^2, 2n) = diag({n / y.var():.4f}, {2 * n})")
off = mle + np.array([0.5, 0.0])
print("half a unit off in mu, numerical Hessian:\n", num_hess(off).round(4))
